// Finite P2 successor vectors; original15-file packet is retained as held source history.
import {prepareOriginalStageAfter as heldPrepare} from 'file:///D:/Development/GitHub/.codex-worktrees/healthroster-v2-money-build-13102026/.codex-tmp/daily-original-stages-after-recorder-source-20261017-97359412021530d3f905efb354049bc4/recorder.mjs';
for(const stage of ['S2','S3'])test('P2 '+stage+' exact done-100/done-99 held counterexample refuses corrected source',()=>{const {a}=vector(stage),done=Date.parse(JSON.parse(a.responseBytes).finishedAt);change(a,'auxAfterBytes',v=>{const f=frames(v);f[0].observedAt=new Date(done-100).toISOString();f[1].observedAt=new Date(done-99).toISOString();});assert.equal(heldPrepare(a).records.length,4);assert.throws(()=>prepareOriginalStageAfter(a),/ACTUAL_AUXILIARY_AFTER_RESPONSE_ORDER_REQUIRED/);});
test('P2 equal response boundary is admitted, fresh order retained and valid four-record bytes unchanged',()=>{for(const stage of ['S1a','S2','S3','S4']){const {a}=vector(stage);if(['S2','S3'].includes(stage)){const done=Date.parse(JSON.parse(a.responseBytes).finishedAt);change(a,'auxAfterBytes',v=>{const f=frames(v);f[0].observedAt=new Date(done).toISOString();f[1].observedAt=new Date(done+1).toISOString();});}assert.deepEqual(prepareOriginalStageAfter(a),heldPrepare(a));}for(const stage of ['S2','S3']){const {a}=vector(stage),done=Date.parse(JSON.parse(a.responseBytes).finishedAt);change(a,'auxAfterBytes',v=>{const f=frames(v);f[0].observedAt=new Date(done).toISOString();f[1].observedAt=new Date(done-1).toISOString();});assert.throws(()=>prepareOriginalStageAfter(a));}});
